(function(){"use strict";const prefersReduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(typeof gsap==="undefined"){console.warn("Sacred Kompass: GSAP not loaded — CSS keyframe fallback active.");document.body.classList.add("no-gsap");document.querySelectorAll(".journey-stage,.reveal,.reveal-left,.reveal-right,.reveal-scale,.section-enter,.stagger-children").forEach(el=>el.classList.add("visible"));return}gsap.registerPlugin(ScrollTrigger);ScrollTrigger.config({ignoreMobileResize:true});let lenis;function initLenis(){if(typeof Lenis==="undefined")return;if(prefersReduced){console.log("Sacred Kompass: prefers-reduced-motion detected. Bypassing Lenis scroll hijacking.");window.skLenisReady=false;window.skLenisPause=()=>{};window.skLenisResume=()=>{};bindScrollToFallback();return}const isTouch=window.matchMedia("(hover: none) and (pointer: coarse)").matches;lenis=new Lenis({duration:prefersReduced?0:1.3,easing:t=>Math.min(1,1.001-Math.pow(2,-10*t)),smooth:!prefersReduced,smoothTouch:!isTouch?true:false,touchMultiplier:1.5,wheelMultiplier:1,normalizeWheel:false,lerp:prefersReduced?1:.08,infinite:false,prevent:node=>node&&typeof node.closest==="function"&&(node.closest(".sk-rc-overlay-box")!==null||node.closest(".sk-founder-modal-box")!==null||node.closest(".cta-section form, .sk-cta-section form, #contact form")!==null||node.closest(".select2-dropdown")!==null||node.closest(".select2-container")!==null||node.closest(".select2-results__options")!==null||node.closest(".forminator-select-dropdown")!==null)});gsap.ticker.add(time=>lenis.raf(time*1e3));gsap.ticker.lagSmoothing(0);lenis.on("scroll",ScrollTrigger.update);window.skLenisReady=true;window.skLenisPause=()=>lenis&&lenis.stop();window.skLenisResume=()=>lenis&&lenis.start();if(window.location.hash){setTimeout(function(){var hash=window.location.hash;var target=document.querySelector(hash);if(!target&&hash==="#collective")target=document.getElementById("founders");if(!target&&hash==="#sk-philosophy-strip")target=document.getElementById("philosophy");if(target){var nav=document.getElementById("sk-sidenav");lenis.scrollTo(target,{offset:-(nav?nav.offsetHeight:64),duration:prefersReduced?0:1.3,easing:function(t){return 1-Math.pow(1-t,5)}})}},350)}document.querySelectorAll('a[href^="#"], a[href*="/#"]').forEach(a=>{a.addEventListener("click",e=>{const href=a.getAttribute("href")||"";const hashIdx=href.lastIndexOf("#");if(hashIdx===-1)return;const id=href.slice(hashIdx+1);if(!id)return;let target=document.getElementById(id);if(!target&&id==="collective")target=document.getElementById("founders");if(!target&&id==="sk-philosophy-strip")target=document.getElementById("philosophy");if(!target)return;e.preventDefault();if(typeof window.skCloseSidenav==="function"){window.skCloseSidenav()}const nav=document.getElementById("sk-sidenav");lenis.scrollTo(target,{offset:-(nav?nav.offsetHeight:64),duration:prefersReduced?0:1.3,easing:t=>1-Math.pow(1-t,5)})})})}function bindScrollToFallback(){if(window.location.hash){setTimeout(function(){var hash=window.location.hash;var target=document.querySelector(hash);if(!target&&hash==="#collective")target=document.getElementById("founders");if(!target&&hash==="#sk-philosophy-strip")target=document.getElementById("philosophy");if(target){var nav=document.getElementById("sk-sidenav");const top=target.getBoundingClientRect().top+window.scrollY-(nav?nav.offsetHeight:64);window.scrollTo({top:top,behavior:prefersReduced?"auto":"smooth"})}},350)}document.querySelectorAll('a[href^="#"], a[href*="/#"]').forEach(a=>{a.addEventListener("click",e=>{const href=a.getAttribute("href")||"";const hashIdx=href.lastIndexOf("#");if(hashIdx===-1)return;const id=href.slice(hashIdx+1);if(!id)return;let target=document.getElementById(id);if(!target&&id==="collective")target=document.getElementById("founders");if(!target&&id==="sk-philosophy-strip")target=document.getElementById("philosophy");if(!target)return;e.preventDefault();if(typeof window.skCloseSidenav==="function"){window.skCloseSidenav()}const nav=document.getElementById("sk-sidenav");const top=target.getBoundingClientRect().top+window.scrollY-(nav?nav.offsetHeight:64);window.scrollTo({top:top,behavior:prefersReduced?"auto":"smooth"})})})}function initProgressBar(){let bar=document.querySelector(".sk-progress");if(!bar){bar=document.createElement("div");bar.className="sk-progress";bar.id="sk-progress-bar";document.body.prepend(bar)}else if(!bar.id){bar.id="sk-progress-bar"}ScrollTrigger.create({trigger:document.documentElement,start:"top top",end:"bottom bottom",onUpdate(self){bar.style.transform="scaleX("+self.progress.toFixed(4)+")"}})}function initNav(){}function initHeroParallax(){if(prefersReduced)return;const img=document.querySelector(".hero-bg-image img");if(!img)return;const heroTrigger=document.querySelector(".hero--split, .hero--fullscreen, #hero, .hero-section");if(!heroTrigger)return;gsap.fromTo(img,{yPercent:0},{yPercent:18,ease:"none",scrollTrigger:{trigger:heroTrigger,start:"top top",end:"bottom top",scrub:2.5}});const overlay=document.querySelector(".hero-bg-overlay")}function initScrollReveals(){if(prefersReduced){document.querySelectorAll(".reveal, .reveal-left, .reveal-right, .reveal-scale, .reveal-fade, .reveal-cta, .section-enter, .stagger-children").forEach(el=>{el.style.opacity="1";el.style.transform="none";if(el.classList.contains("stagger-children")){Array.from(el.children).forEach(k=>{k.style.opacity="1";k.style.transform="none"})}});return}document.querySelectorAll(".reveal,.reveal-left,.reveal-right,.reveal-scale,.reveal-fade,.reveal-cta,.section-enter,.stagger-children").forEach(el=>{el.style.transition="none"});const floatEase="power4.out";gsap.utils.toArray(".reveal").forEach(el=>{const inCta=el.closest(".cta-section, .sk-cta-section");if(inCta)return;if(el.matches(".display-h2, .av16-heading, .cta-h2, .sk-sp-v4-heading, .display-xl, .sk-spg-hero__title, .sk-spg-cta__heading, .sk-event-single-title, .sk-story-single__title, .sk-archive-heading, .sk-cover-title, .sk-jp-feat-title, .sk-jp-side-title, h1"))return;gsap.fromTo(el,{opacity:0,y:40,scale:.99},{opacity:1,y:0,scale:1,duration:1.1,delay:+el.dataset.delay||0,ease:floatEase,scrollTrigger:{trigger:el,start:"top 90%",toggleActions:"play none none none"}})});gsap.utils.toArray(".reveal-left").forEach(el=>{gsap.fromTo(el,{opacity:0,x:-40,scale:.99},{opacity:1,x:0,scale:1,duration:1.15,delay:+el.dataset.delay||0,ease:floatEase,scrollTrigger:{trigger:el,start:"top 90%",toggleActions:"play none none none"}})});gsap.utils.toArray(".reveal-right").forEach(el=>{gsap.fromTo(el,{opacity:0,x:40,scale:.99},{opacity:1,x:0,scale:1,duration:1.15,delay:+el.dataset.delay||0,ease:floatEase,scrollTrigger:{trigger:el,start:"top 90%",toggleActions:"play none none none"}})});gsap.utils.toArray(".reveal-scale").forEach(el=>{gsap.fromTo(el,{opacity:0,scale:.94,y:20},{opacity:1,scale:1,y:0,duration:1.2,delay:+el.dataset.delay||0,ease:floatEase,scrollTrigger:{trigger:el,start:"top 90%",toggleActions:"play none none none"}})});gsap.utils.toArray(".reveal-fade").forEach(el=>{gsap.fromTo(el,{opacity:0},{opacity:1,duration:1.4,delay:+el.dataset.delay||0,ease:"power2.out",scrollTrigger:{trigger:el,start:"top 88%",toggleActions:"play none none none"}})});gsap.utils.toArray(".reveal-cta").forEach(el=>{gsap.fromTo(el,{opacity:0,scale:.97},{opacity:1,scale:1,duration:1.3,delay:+el.dataset.delay||0,ease:floatEase,scrollTrigger:{trigger:el,start:"top 90%",toggleActions:"play none none none"}})});gsap.utils.toArray(".section-enter").forEach(el=>{gsap.fromTo(el,{opacity:0,y:60,scale:.98},{opacity:1,y:0,scale:1,duration:1.35,ease:floatEase,scrollTrigger:{trigger:el,start:"top 88%",toggleActions:"play none none none"}})});gsap.utils.toArray(".stagger-children").forEach(parent=>{const kids=[...parent.children];kids.forEach(k=>{k.style.transition="none"});gsap.fromTo(kids,{opacity:0,y:28,scale:.98},{opacity:1,y:0,scale:1,duration:1,stagger:{amount:.4,ease:"power2.inOut"},ease:floatEase,scrollTrigger:{trigger:parent,start:"top 85%",toggleActions:"play none none none"}})})}function initSectionParallax(){if(prefersReduced)return;[["parallax-slow",-20],["parallax-med",-38],["parallax-fast",-60]].forEach(([cls,y])=>{gsap.utils.toArray(`.${cls}`).forEach(el=>{gsap.fromTo(el,{y:0},{y:y,ease:"none",scrollTrigger:{trigger:el.closest("section")||el.parentElement,start:"top bottom",end:"bottom top",scrub:2}})})});gsap.utils.toArray(".hero-bg-image img, .cinematic-image-wrap img, .sk-cover-image, .founder-card img").forEach(img=>{const parent=img.parentElement;if(parent){parent.style.overflow="hidden"}gsap.set(img,{scale:1.15,transformOrigin:"center center"});gsap.to(img,{yPercent:15,ease:"none",scrollTrigger:{trigger:parent||img,start:"top bottom",end:"bottom top",scrub:true}})})}function initAboutTagline(){if(prefersReduced)return;const taglineInner=document.querySelector(".av16-tagline-inner");if(!taglineInner)return;gsap.fromTo(taglineInner,{opacity:0,y:50},{opacity:1,y:0,duration:1.2,ease:"power3.out",scrollTrigger:{trigger:taglineInner,start:"top 90%",toggleActions:"play none none none"},onComplete:function(){const parent=taglineInner.closest(".av16-tagline");if(parent){parent.classList.add("start-wave")}}})}function initTradTags(){if(prefersReduced){document.querySelectorAll(".trad-tag").forEach(tag=>{tag.style.opacity="1";tag.style.transform="none"});return}const tags=gsap.utils.toArray(".trad-tag");if(!tags.length)return;gsap.fromTo(tags,{opacity:0,scale:.75,y:14},{opacity:1,scale:1,y:0,duration:.8,stagger:{amount:.8},ease:"back.out(1.8)",scrollTrigger:{trigger:".tradition-tags",start:"top 92%",toggleActions:"play none none none"}})}function initFounders(){const cards=gsap.utils.toArray(".founder-card");if(!cards.length)return;cards.forEach(c=>{c.style.opacity="1";c.style.transform="none"});if(prefersReduced)return;const section=cards[0].closest("section")||cards[0].parentElement;const rect=section.getBoundingClientRect();const alreadyVisible=rect.top<window.innerHeight*.9;if(alreadyVisible)return;gsap.fromTo(cards,{opacity:0,x:-50,scale:.97},{opacity:1,x:0,scale:1,duration:1.2,stagger:.15,ease:"power4.out",scrollTrigger:{trigger:section,start:"top 88%",toggleActions:"play none none none",onEnter(){setTimeout(()=>cards.forEach(c=>{c.style.opacity="1";c.style.transform="none"}),1800)}}})}function initFaq(){if(prefersReduced){document.querySelectorAll(".faq-item, .sk-faq-item").forEach(el=>{el.style.opacity="1";el.style.transform="none"});return}const items=gsap.utils.toArray(".faq-item, .sk-faq-item");if(!items.length)return;gsap.fromTo(items,{opacity:0,y:20},{opacity:1,y:0,duration:.8,stagger:.15,ease:"power2.out",scrollTrigger:{trigger:".faq-section, .sk-faq-section",start:"top 90%",toggleActions:"play none none none"}})}function initCta(){const cta=document.querySelector(".cta-section, .sk-cta-section");if(!cta)return;if(prefersReduced){cta.style.opacity="1";cta.style.transform="none";cta.querySelectorAll(".cta-text-col, .cta-form-col").forEach(col=>{col.style.opacity="1";col.style.transform="none"});return}const cols=cta.querySelectorAll(".cta-text-col, .cta-form-col");if(cols.length){gsap.fromTo(cols,{opacity:0,scale:.97},{opacity:1,scale:1,duration:1.3,stagger:.15,ease:"power4.out",scrollTrigger:{trigger:cta,start:"top 88%",toggleActions:"play none none none"}})}else{gsap.fromTo(cta,{opacity:0,scale:.97},{opacity:1,scale:1,duration:1.4,ease:"power4.out",scrollTrigger:{trigger:cta,start:"top 88%",toggleActions:"play none none none"}})}}function initSplitText(){if(prefersReduced)return;if(typeof SplitType==="undefined")return;const headlines=gsap.utils.toArray(".display-h2, .av16-heading, .cta-h2, .sk-sp-v4-heading, .display-xl, .sk-spg-hero__title, .sk-spg-cta__heading, .sk-event-single-title, .sk-story-single__title, .sk-archive-heading, .sk-cover-title, .sk-jp-feat-title, .sk-jp-side-title, h1:not(.sr-only)");if(!headlines.length)return;const splits=[];const triggers=[];function doSplit(){triggers.forEach(t=>t.kill());triggers.length=0;splits.forEach(s=>s.revert());splits.length=0;headlines.forEach(el=>{const inHero=el.closest(".sk-home-hero, .hero--split, .hero-left");const split=new SplitType(el,{types:"lines, words"});splits.push(split);if(el.classList.contains("sk-heading-revealed")){gsap.set(el,{opacity:1,y:0,scale:1});gsap.set(split.words,{opacity:1,yPercent:0,rotationZ:0});return}gsap.set(el,{opacity:0,y:0,scale:1});gsap.set(split.lines,{overflow:"hidden"});gsap.set(split.words,{opacity:0,yPercent:120,rotationZ:2});const triggerConfig=inHero?{trigger:el,start:"top 100%",toggleActions:"play none none none"}:{trigger:el,start:"top 84%",toggleActions:"play none none none"};triggerConfig.onEnter=()=>el.classList.add("sk-heading-revealed");const pAnim=gsap.to(el,{opacity:1,y:0,scale:1,duration:.05,scrollTrigger:triggerConfig});if(pAnim.scrollTrigger)triggers.push(pAnim.scrollTrigger);const cAnim=gsap.to(split.words,{yPercent:0,opacity:1,rotationZ:0,ease:"power4.out",duration:1.2,stagger:.04,scrollTrigger:triggerConfig});if(cAnim.scrollTrigger)triggers.push(cAnim.scrollTrigger)})}doSplit();let resizeTimer;let lastWidth=window.innerWidth;window.addEventListener("resize",()=>{if(window.innerWidth===lastWidth)return;lastWidth=window.innerWidth;clearTimeout(resizeTimer);resizeTimer=setTimeout(doSplit,200)},{passive:true})}function initCurtainReveal(){if(prefersReduced){document.querySelectorAll(".cinematic-image-wrap").forEach(wrap=>{wrap.classList.add("is-revealed")});return}gsap.utils.toArray(".cinematic-image-wrap").forEach(wrap=>{ScrollTrigger.create({trigger:wrap,start:"top 85%",toggleActions:"play none none none",onEnter(){wrap.classList.add("is-revealed")}})})}function initJournalCards(){if(prefersReduced){document.querySelectorAll(".sk-jp-card--animated").forEach(el=>{el.style.opacity="1";el.style.transform="none"});return}const yOffsets=[40,52,64];gsap.utils.toArray(".sk-jp-card--animated").forEach((el,i)=>{gsap.fromTo(el,{opacity:0,y:yOffsets[i]||40},{opacity:1,y:0,duration:.85,delay:i*.14,ease:"power2.out",scrollTrigger:{trigger:el,start:"top 90%",toggleActions:"play none none none"}})})}function initPhilosophyStripPause(){const strip=document.getElementById("philosophy");if(!strip)return;strip.addEventListener("focusin",()=>strip.dispatchEvent(new CustomEvent("sk:strip:pause")));strip.addEventListener("focusout",e=>{if(!strip.contains(e.relatedTarget)){strip.dispatchEvent(new CustomEvent("sk:strip:resume"))}})}function init(){initLenis();initProgressBar();initNav();initHeroParallax();initScrollReveals();initAboutTagline();initSectionParallax();initTradTags();initFounders();initFaq();initCta();initSplitText();initCurtainReveal();initJournalCards();initPhilosophyStripPause();let refreshTimer;function scheduleRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>ScrollTrigger.refresh(),60)}document.fonts.ready.then(scheduleRefresh);window.addEventListener("resize",scheduleRefresh,{passive:true})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();